const links = {};   // código -> URL (o estado do servidor)

function encurtar(url) {
  const codigo = gerarCodigo();
  links[codigo] = url;
  return codigo;
}
function resolver(codigo) {
  return links[codigo] || null;   // null = código não existe
}

// Pseudo-rotas de um servidor Node (ex.: Express)
app.post('/encurtar', (req, res) => {
  const codigo = encurtar(req.body.url);
  res.json({ curto: `${BASE}/${codigo}` });   // POST cria
});
app.get('/:codigo', (req, res) => {
  const url = resolver(req.params.codigo);
  if (!url) return res.status(404).send('não existe');
  res.redirect(302, url);                       // 302: passa sempre por aqui
});

function gerarCodigo() {
  let c;
  do { c = aleatorio(6); } while (links[c]);   // repete até achar um livre (sem colisão)
  return c;
}
function urlValida(u) {
  try { const x = new URL(u); return x.protocol === 'http:' || x.protocol === 'https:'; }
  catch { return false; }
}
